package com.ruoyi.medical.workflow;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.medical.workflow.WorkflowProtocol.*;
import static com.ruoyi.medical.workflow.TaskRunStageProtocolV2.*;
import static com.ruoyi.medical.workflow.TaskRunRecoveryProtocolV2.*;
class TaskRunStageProtocolV2Test {
    static final String H="a".repeat(64);final Reference ref=new Reference("1.0.0",id(),id(),id(),ExecutionKind.TASK,id(),H,id(),9999999999999L,10,10,1,1000,1000,1000,"stage-control","stage-professional");final String step=id(),graph=id(),plan=id();
    FieldCompletionV2 completion(){return new FieldCompletionV2("2.0.0","N03","FIELD_TARGET",ref.runId(),id(),id(),id(),H,id(),1,id(),H,H);}
    StageCommitV2 commit(FieldCompletionV2 c,String state){return new StageCommitV2("2.0.0","N03",H,graph,H,c,state,id(),H);}
    Plan base(List<RequiredStage> stages,State status){var result=new Step(step,H,List.of(),true,State.SUCCEEDED,1,id(),null,List.of());return new Plan(H,plan,status,null,status==State.SUCCEEDED?new FinalReceipt(ref.runId(),H,status,id()):null,List.of(result),List.of(new PlannedStep(step,List.of(),true)),graph,H,stages);}
    RunPlanV2 loaded(Plan p,List<StageCommitV2> receipts){return new RunPlanV2("2.0.0",p,List.of(),List.of(),receipts,receipts.stream().map(r->{var c=r.completion();return new StageCommandV2("2.0.0",c.stageKind(),c.runId(),c.commandId(),c.stepId(),c.inputId(),c.inputSha256());}).distinct().toList());}
    @Test void checkedResultIsNotAutomaticallyFulfillment(){var p=base(List.of(new RequiredStage("N03",H,null,null)),State.RUNNING);var blocked=commit(completion(),"BLOCKED");var loaded=loaded(p,List.of(blocked));assertEquals(1,loaded.require(ref).size());assertFalse(stagesSatisfied(p,loaded.stageCommits()));assertThrows(IllegalArgumentException.class,()->loaded(base(p.requiredStages(),State.SUCCEEDED),List.of(blocked)).require(ref));}
    @Test void n03CannotHideLaterObligationsOrBeDoubleCounted(){var r=commit(completion(),"SATISFIED");var obligations=List.of(new RequiredStage("N03",H,null,null),new RequiredStage("N04",H,null,null));var p=base(obligations,State.RUNNING);assertFalse(stagesSatisfied(p,List.of(r)));assertThrows(IllegalArgumentException.class,()->loaded(p,List.of(r,r)).require(ref));assertThrows(IllegalArgumentException.class,()->loaded(base(obligations,State.SUCCEEDED),List.of(r)).require(ref));}
    @Test void v2TypedSuccessDoesNotMutateLegacyStageOrCreateArtifactOutput(){var obligation=new RequiredStage("N03",H,null,null);var p=base(List.of(obligation),State.SUCCEEDED);var r=commit(completion(),"SATISFIED");assertEquals(1,loaded(p,List.of(r)).require(ref).size());assertEquals(StageDisposition.PENDING,p.requiredStages().get(0).disposition());assertTrue(p.steps().get(0).outputs().isEmpty());assertThrows(IllegalArgumentException.class,()->WorkflowPlan.require(ref,p));}
    @Test void closedStageWireRejectsCallerAuthorityAndWrongCommand()throws Exception{var schema=new TaskRunStageSchemaV2();var c=completion();var request=new TaskRunStageSchemaV2.Request("EXECUTE_STAGE",ref,"N03",c.commandId(),null);assertEquals(request,schema.read(schema.request(request)));var json=new ObjectMapper();var n=(com.fasterxml.jackson.databind.node.ObjectNode)json.readTree(schema.request(request));n.put("actor_id",id());assertThrows(Exception.class,()->schema.read(json.writeValueAsBytes(n)));assertThrows(IllegalArgumentException.class,()->schema.response(new TaskRunStageSchemaV2.Request("EXECUTE_STAGE",ref,"N03",id(),null),c));var result=schema.response(request,c);assertEquals(c,schema.response(json.writeValueAsBytes(result),request));((com.fasterxml.jackson.databind.node.ObjectNode)result.required("result")).put("result_artifact_id",id());assertThrows(Exception.class,()->schema.response(json.writeValueAsBytes(result),request));}
    @Test void typedCommitRequiresIndependentOriginalCommand(){var p=base(List.of(new RequiredStage("N03",H,null,null)),State.RUNNING);var r=commit(completion(),"SATISFIED");assertThrows(IllegalArgumentException.class,()->new RunPlanV2("2.0.0",p,List.of(),List.of(),List.of(r)).require(ref));var pending=new StageRecoveryV2("2.0.0","PENDING","N03",r.completion().commandId(),null,null);pending.require(ref,"N03",r.completion().commandId());assertThrows(IllegalArgumentException.class,()->new StageRecoveryV2("2.0.0","PENDING","N03",r.completion().commandId(),r.completion(),null));}
    @Test void resultIdentityCannotUseArtifactOrGenerationZero(){assertThrows(IllegalArgumentException.class,()->new FieldCompletionV2("2.0.0","N03","ARTIFACT",ref.runId(),id(),id(),id(),H,id(),1,id(),H,H));assertThrows(IllegalArgumentException.class,()->new FieldCompletionV2("2.0.0","N03","FIELD_TARGET",ref.runId(),id(),id(),id(),H,id(),0,id(),H,H));}
    static String id(){return UUID.randomUUID().toString();}
}
